// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.system.handlerimport timber.log.Timberimport com.roshan.persona.brain.skill.SystemOperationimport com.roshan.persona.common.AppErrorimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport com.roshan.persona.system.executor.ResourceCategory/** * NOUS — Tethering Handler (Module 10 v2 — Step 10.6, Review 1). * * Toggles Wi-Fi hotspot (tethering) on/off. * * ## Behavior (per strategy §"Privacy & Security — Tethering") * *  - `startTethering` / `stopTethering` via `ConnectivityManager`. *  - Requires `CHANGE_NETWORK_STATE` + `ACCESS_NETWORK_STATE` permissions. *  - **Carrier/OEM blocking**: Some carriers (especially US carriers on *    locked phones) disable tethering entirely. `startTethering` throws *    `IllegalArgumentException` — mapped to `Hardware.Unsupported` with the *    message "Tethering not supported by your carrier". * * ## Idempotent execution (Review 2 Elite 1) * * If tethering is already in the target state, skip the call. * * ## Pre-state capture (Review 2 Fix A) * * Captures the previous on/off state. Undo restores the actual previous state. * * ## Reversibility * * Tethering is reversible — undo turns the hotspot back off (or on if it * was on before). * * ## Resource category * * Tethering uses [ResourceCategory.CONNECTIVITY] — it activates the Wi-Fi * radio in AP mode, sequenced with other connectivity ops. * * ## Hardware-heavy * * Tethering is **hardware-heavy** (radio + CPU + battery) — the executor's * thermal gate will refuse this operation at `THERMAL_SEVERE` (headroom * >= 2.5). * * @see <a href="docs/strategy/module-10-system-strategy-v2.md">§Privacy & Security — Tethering (Review 1)</a> */class TetheringHandler(    private val tetheringService: TetheringService,) : ReversibleHandler<SystemOperation.SetTethering> {    override val id: String = "tethering"    override val displayName: String = "Wi-Fi Hotspot (Tethering) Control"    override val requiredPermissions: Set<String> = setOf(        android.Manifest.permission.CHANGE_NETWORK_STATE,        android.Manifest.permission.ACCESS_NETWORK_STATE,    )    override val resourceCategory: ResourceCategory = ResourceCategory.CONNECTIVITY    override fun isAvailable(): Boolean = tetheringService.isTetheringSupported()    override suspend fun execute(operation: SystemOperation.SetTethering): Result<Unit> {        if (!isAvailable()) {            return Result.Failure(                error = AppError.Hardware.Unsupported("tethering"),                correlationId = CorrelationId.generate(),                durationNanos = 0,            )        }        return try {            val success = if (operation.enabled) {                tetheringService.startTethering()            } else {                tetheringService.stopTethering()            }            if (success) {                Result.Success(Unit, CorrelationId.generate(), 0)            } else {                Result.Failure(                    error = AppError.Hardware.Unknown("tethering"),                    correlationId = CorrelationId.generate(),                    durationNanos = 0,                )            }        } catch (e: IllegalArgumentException) {            // Carrier/OEM blocks tethering.            Timber.tag("TetheringHandler").w("Tethering unsupported by carrier", e)            Result.Failure(                error = AppError.Hardware.Unsupported("tethering", e),                correlationId = CorrelationId.generate(),                durationNanos = 0,            )        } catch (t: Throwable) {            Timber.tag("TetheringHandler").w("execute failed", t)            Result.Failure(                error = AppError.Hardware.Unknown("tethering", t),                correlationId = CorrelationId.generate(),                durationNanos = 0,            )        }    }    override suspend fun capturePreState(operation: SystemOperation.SetTethering): Any? {        return try {            TetheringPreState(wasEnabled = tetheringService.isTetheringActive())        } catch (t: Throwable) {            Timber.tag("TetheringHandler").w("capturePreState failed", t)            null        }    }    override suspend fun restorePreState(operation: SystemOperation.SetTethering, preState: Any?) {        if (preState !is TetheringPreState) return        try {            if (preState.wasEnabled) {                tetheringService.startTethering()            } else {                tetheringService.stopTethering()            }        } catch (t: Throwable) {            Timber.tag("TetheringHandler").w("restorePreState failed", t)        }    }    override suspend fun getCurrentState(): Any? = try {        TetheringPreState(wasEnabled = tetheringService.isTetheringActive())    } catch (t: Throwable) { null }    override suspend fun isAlreadyInTargetState(operation: SystemOperation.SetTethering): Boolean {        return try {            tetheringService.isTetheringActive() == operation.enabled        } catch (t: Throwable) {            false        }    }    override fun describeOperation(operation: SystemOperation.SetTethering): String =        if (operation.enabled) "Wi-Fi hotspot turned on" else "Wi-Fi hotspot turned off"    // ─── Pre-state serialization (audit defect B fix) ─────────────────────    override fun serializePreState(preState: Any?): String? {        if (preState == null) return null        if (preState !is TetheringPreState) {            return com.roshan.persona.system.undo.SystemOperationSerializer.serializePreState(preState)        }        return "{\"type\":\"TetheringPreState\",\"wasEnabled\":${preState.wasEnabled}}"    }    override fun deserializePreState(json: String?): Any? {        if (json == null) return null        val map = try {            com.roshan.persona.system.undo.SystemOperationSerializer.parseJsonObject(json)        } catch (t: Throwable) {            return com.roshan.persona.system.undo.SystemOperationSerializer.deserializePreState(json)        }        return when (map["type"] as? String) {            "TetheringPreState" -> TetheringPreState(wasEnabled = (map["wasEnabled"] as? Boolean) ?: false)            else -> com.roshan.persona.system.undo.SystemOperationSerializer.deserializePreState(json)        }    }    /** Captured pre-state for tethering (previous on/off). */    data class TetheringPreState(val wasEnabled: Boolean)}
